 sealed class Curve {public int Zone,Soil;public string Source;public double Km,Na,Nv,Ca,Cv,Ts,T0,I,R,Extra,G,Scale,Damping;public List<double[]> Points;}
 Curve Compute(){var c=new Curve{Zone=Value("Zone").StartsWith("Zone 4")?4:2,Soil=Array.IndexOf(SoilNames,Value("Soil")),Source=Value("Source"),Km=Number("Distance"),R=Number("R"),Extra=Number("ExtraScale"),Damping=Number("Damping")};
  if(c.Soil<0)throw new Exception("Choose a soil profile type.");if(c.Km<0)throw new Exception("Distance must be zero or more.");if(c.R<=0)throw new Exception("R must be greater than zero.");if(c.Extra<=0)throw new Exception("Additional scale factor must be greater than zero.");if(c.Damping<=0||c.Damping>=1)throw new Exception("Damping ratio must be between 0 and 1.");
  double tMax=Number("TMax"),step=Number("Step");if(tMax<=0||tMax>10)throw new Exception("Last period must be more than 0 and up to 10 s.");if(step<.005||step>tMax)throw new Exception("Period step must be at least 0.005 s and not more than the last period.");if(tMax/step>400)throw new Exception("Too many points: use a larger period step (400 points at most).");
  c.Na=c.Zone==4?NscpSpectrum.Na(c.Source,c.Km):1;c.Nv=c.Zone==4?NscpSpectrum.Nv(c.Source,c.Km):1;c.Ca=NscpSpectrum.Ca(c.Zone,c.Soil,c.Na);c.Cv=NscpSpectrum.Cv(c.Zone,c.Soil,c.Nv);c.Ts=c.Cv/(2.5*c.Ca);c.T0=.2*c.Ts;
  c.I=Value("Importance").Contains("1.50")?1.5:Value("Importance").Contains("1.25")?1.25:1.0;c.G=Value("Unit").StartsWith("Milli")?9806.65:9.80665;c.Scale=c.G*c.I/c.R*c.Extra;c.Points=NscpSpectrum.Points(c.Ca,c.Cv,tMax,step);return c;}
 /* rho and regularity from the Load Combinations sheet (owner: "link mo lahat ng kailangan inputs sa isat isa") */
 static Dictionary<string,string> LcLink(){var d=DesignLoadsLink.Get("load-combinations");return d!=null&&d.ContainsKey("structure")?d:null;}
 void ApplyLcLink(){if(!On("LcLinked"))return;var d=LcLink();if(d==null)return;string rho;if(d.TryGetValue("rho",out rho)&&rho!=""&&Value("Rho")!=rho)Inputs["Rho"].Text=rho;
  var combo=Inputs["Regularity"] as ComboBox;if(combo!=null){string want=d["structure"]=="C"?"Irregular":"Regular";for(int i=0;i<combo.Items.Count;i++)if(Convert.ToString(combo.Items[i]).StartsWith(want+" ")&&combo.SelectedIndex!=i)combo.SelectedIndex=i;}}
 StaticLateralResult Static(Curve c){ApplyLcLink();double omega=Number("Omega"),rho=Number("Rho"),dyn;if(!double.TryParse(Value("DynamicV"),NumberStyles.Float,CultureInfo.InvariantCulture,out dyn))dyn=0;
  var res=StaticLateralForce.Compute(c.Zone,c.Ca,c.Cv,c.Na,c.Nv,c.I,c.R,Value("System"),Value("Levels"),omega,rho,!Value("Regularity").StartsWith("Irregular"),dyn);/* Ca, I and Omega0 for the Load Combinations sheet */EarthquakeLink.Save(res,c.Soil>=0?c.Soil+1:0);DesignLoadsLink.Set("earthquake-levels",new Dictionary<string,string>{{"levels",Value("Levels")}});return res;}
 static string F(double v,string format){return v.ToString(format,CultureInfo.InvariantCulture);}
 string Staad(Curve c){var b=new StringBuilder();int load;if(!int.TryParse(Value("LoadNo"),out load)||load<1)throw new Exception("First load case number must be a whole number.");string[] axes=Value("Axes").StartsWith("X and Z")?new[]{"X","Z"}:new[]{"X","Y"};
  b.AppendLine("* NSCP 2015 design response spectrum - Zone "+c.Zone+", soil "+NscpSpectrum.Soils[c.Soil]+", source "+c.Source+" at "+F(c.Km,"0.##")+" km");b.AppendLine("* Ca = "+F(c.Ca,"0.####")+", Cv = "+F(c.Cv,"0.####")+", T0 = "+F(c.T0,"0.####")+" s, Ts = "+F(c.Ts,"0.####")+" s; ordinates in g");b.AppendLine("* ACC SCALE = g x I / R x factor = "+F(c.G,"0.#####")+" x "+F(c.I,"0.##")+" / "+F(c.R,"0.##")+" x "+F(c.Extra,"0.####"));
  for(int d=0;d<axes.Length;d++){b.AppendLine("LOAD "+(load+d)+" LOADTYPE SEISMIC-H TITLE RSA "+axes[d]);b.AppendLine("SPECTRUM "+Value("Method")+" "+axes[d]+" 1 ACC SCALE "+F(c.Scale,"0.######")+" DAMP "+F(c.Damping,"0.###")+" LIN");
   for(int i=0;i<c.Points.Count;i+=4){var pairs=c.Points.Skip(i).Take(4).Select(p=>F(p[0],"0.####")+" "+F(p[1],"0.#####"));b.AppendLine(string.Join("; ",pairs));/* ";" separates STAAD lines, so each pair is its own data line */}}
  return b.ToString().TrimEnd();}
 /* the static lateral force procedure as STAAD's UBC 1997 definition (NSCP 2015 208.5.2): Z, I, R, soil STYP 1 SA .. 5 SE, Na / Nv and the
    Method A period as PX / PZ (seconds, so no unit question with CT) */
 string Elf(Curve c){StaticLateralResult st=null;string err=null;try{st=Static(c);}catch(Exception ex){err=ex.Message;}var b=new StringBuilder();
  b.AppendLine("* NSCP 2015 static lateral force procedure (208.5.2), UBC 1997 in STAAD");b.AppendLine("* Zone "+c.Zone+" (Z = "+(c.Zone==4?"0.40":"0.20")+"), soil "+NscpSpectrum.Soils[c.Soil]+" (STYP "+(c.Soil+1)+"), source "+c.Source+" at "+F(c.Km,"0.##")+" km");
  b.AppendLine("* Ca = "+F(c.Ca,"0.####")+", Cv = "+F(c.Cv,"0.####")+", Na = "+F(c.Na,"0.###")+", Nv = "+F(c.Nv,"0.###")+", I = "+F(c.I,"0.##")+", R = "+F(c.R,"0.##"));
  if(st!=null){b.AppendLine("* T (Method A) = Ct hn^3/4 = "+F(st.Ct,"0.####")+" x "+F(st.Hn,"0.##")+"^0.75 = "+F(st.T,"0.###")+" s");b.AppendLine("* sheet check: W = "+F(st.W,"0.#")+" kN, V = "+F(st.V,"0.##")+" kN ("+F(st.Cs,"0.####")+" W), Ft = "+F(st.Ft,"0.##")+" kN");}
  else b.AppendLine("* period not computed ("+err+"); STAAD computes it");
  b.AppendLine("DEFINE UBC LOAD");b.AppendLine("ZONE "+(c.Zone==4?"0.4":"0.2")+" I "+F(c.I,"0.##")+" RWX "+F(c.R,"0.##")+" RWZ "+F(c.R,"0.##")+" STYP "+(c.Soil+1)+" NA "+F(c.Na,"0.###")+" NV "+F(c.Nv,"0.###")+(st!=null?" PX "+F(st.T,"0.###")+" PZ "+F(st.T,"0.###"):""));
  b.AppendLine("* seismic weight W (208.5.1.1): dead + 25 % storage live");b.AppendLine("SELFWEIGHT 1");b.AppendLine("* add FLOOR / MEMBER / JOINT WEIGHT, or REFERENCE LOAD Y");b.AppendLine("* with the dead reference loads (e.g. R1 1.0)");
  b.AppendLine("* EQ load cases (UBC LOAD X / Z): Load Combinations sheet");
  return StaadLines.Wrap(b.ToString().TrimEnd());}
 string Table(){var c=Compute();var b=new StringBuilder("T (s)\tSa (g)\r\n");foreach(var p in c.Points)b.Append(F(p[0],"0.####")+"\t"+F(p[1],"0.#####")+"\r\n");return StaadLines.Wrap(b.ToString());/* STAAD lines kept to 72 columns */}
 void Refresh0(){if(Restoring)return;try{var c=Compute();chart.Points=c.Points;chart.T0=c.T0;chart.Ts=c.Ts;chart.Invalidate();staad.Text=Staad(c).Replace("\n","\r\n").Replace("\r\r\n","\r\n");elf.Text=Elf(c).Replace("\n","\r\n").Replace("\r\r\n","\r\n");summary.ForeColor=PowTheme.Teal;string sv="";try{var st=Static(c);sv="\nStatic: T = "+F(st.T,"0.###")+" s   W = "+F(st.W,"0.#")+" kN   V = "+F(st.V,"0.##")+" kN ("+F(st.Cs,"0.####")+" W)   Ft = "+F(st.Ft,"0.##")+" kN"+(st.DynamicFactor>0?"   dynamic scale factor = "+F(st.DynamicFactor,"0.###"):"");}catch(Exception ex){sv="\nStatic lateral force: "+ex.Message;}
   summary.Text="Ca = "+F(c.Ca,"0.###")+"   Cv = "+F(c.Cv,"0.###")+"   Na = "+F(c.Na,"0.###")+"   Nv = "+F(c.Nv,"0.###")+"   T0 = "+F(c.T0,"0.###")+" s   Ts = "+F(c.Ts,"0.###")+" s   peak 2.5Ca = "+F(2.5*c.Ca,"0.###")+" g   ACC SCALE = "+F(c.Scale,"0.####")+sv;}
  catch(Exception ex){summary.ForeColor=Color.Firebrick;summary.Text=ex.Message;staad.Text="";elf.Text="";chart.Points=new List<double[]>();chart.Invalidate();}}
 /* Earthquake Load tab (owner, 19 November 2026): coordinates -> nearest active fault (HazardHunterPH, DOST-PHIVOLCS), seismic source
    type (Table 208-3) and historical earthquakes (USGS); the distance and source type feed the spectrum inputs */
 FaultSite fault;List<QuakeEvent> quakes=new List<QuakeEvent>();readonly Label faultSummary=new Label{Width=1000,Height=150,Tag="FullWidth",Font=ModernUi.Body};readonly Label sourceSummary=new Label{Width=1000,Height=52,Tag="FullWidth",Font=ModernUi.Strong,ForeColor=PowTheme.Teal};
 FaultEstimate estimate;string autoMmax="",autoSlip="",autoLength="";List<FaultTrace> kmzTraces=new List<FaultTrace>(FaultTraces.MapLines),picked;Label kmzStatus;readonly EarthquakeMapView map=new EarthquakeMapView{Width=1000,Height=560,Tag="FullWidth"};
 readonly DataGridView quakeGrid=new DataGridView{Width=1000,Height=340,Tag="FullWidth",ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};Button lookUp;
 void BuildEarthquakeTab(){var eq=Section("Earthquake Load","Enter the site coordinates and look up the site: the nearest active fault, ground shaking and liquefaction come from HazardHunterPH (DOST-PHIVOLCS / GeoRiskPH) and the earthquake history from the USGS catalog. The fault distance and seismic source type are copied to Site and structure. Verify against the PHIVOLCS active fault map.");
  NumberField(eq,"Latitude","Latitude N (decimal degrees)","");NumberField(eq,"Longitude","Longitude E (decimal degrees)","");NumberField(eq,"Radius","Earthquake search radius km","100");NumberField(eq,"MinMagnitude","Minimum magnitude","5");NumberField(eq,"FromYear","Earthquakes from year","1900");NumberField(eq,"RuptureLength","Fault rupture length L km (Wells and Coppersmith)","");NumberField(eq,"Mmax","Fault maximum magnitude Mmax","");/* owner (24 November 2026, "override Mmax based on Geotechnical Report"): a magnitude from the geotechnical report wins over every automatic estimate */NumberField(eq,"GeoMmax","Mmax from the geotechnical report (overrides the estimate; blank = estimate)","");NumberField(eq,"GeoReport","Geotechnical report (title, firm, date)","");EnableWhen(()=>Value("GeoMmax")=="","Mmax","RuptureLength");NumberField(eq,"SlipRate","Fault slip rate mm/yr","");
  var actions=new FlowLayoutPanel{Width=1000,Height=48,Tag="FullWidth"};lookUp=new Button{Text="Look up site",AutoSize=true};lookUp.Click+=async(s,e)=>{await LookUp();};actions.Controls.Add(lookUp);
  /* the PHIVOLCS active fault map (KMZ of image tiles) under the earthquake map */var kmz=new Button{Text="Load PHIVOLCS fault map (KMZ)",AutoSize=true};kmz.Click+=async(s,e)=>{string path=null;using(var d=new OpenFileDialog{Filter="PHIVOLCS / Google Earth KMZ|*.kmz"})if(d.ShowDialog(this)==DialogResult.OK)path=d.FileName;if(path!=null)await LoadKmz(path,kmz);};actions.Controls.Add(kmz);
  var clear=new Button{Text="Clear fault map",AutoSize=true};clear.Click+=(s,e)=>{map.Overlay=new List<KeyValuePair<RectangleF,Image>>();kmzTraces=new List<FaultTrace>(FaultTraces.MapLines);map.Extra=kmzTraces;kmzStatus.Text="";if(estimate!=null&&estimate.Catalog=="KMZ"){picked=null;ChooseFault(false);}map.Invalidate();};actions.Controls.Add(clear);kmzStatus=new Label{AutoSize=true,ForeColor=PowTheme.Muted,Padding=new Padding(6,8,0,0)};actions.Controls.Add(kmzStatus);eq.Controls.Add(actions);
  map.Extra=kmzTraces;map.Picked+=(t,add)=>PickFault(t,add);
  eq.Controls.Add(sourceSummary);eq.Controls.Add(faultSummary);eq.Controls.Add(new Label{Text="EARTHQUAKE MAP (circles by magnitude, colour by depth; fault traces, the site's fault in red)",Width=1000,Height=30,Tag="FullWidth",Font=ModernUi.Strong,ForeColor=PowTheme.Teal,Padding=new Padding(0,8,0,0)});eq.Controls.Add(map);eq.Controls.Add(new Label{Text="HISTORICAL EARTHQUAKES (USGS ANSS Comprehensive Catalog)",Width=1000,Height=30,Tag="FullWidth",Font=ModernUi.Strong,ForeColor=PowTheme.Teal,Padding=new Padding(0,8,0,0)});eq.Controls.Add(quakeGrid);
  foreach(var h in new[]{"DATE (UTC)","MAGNITUDE","DEPTH (km)","DISTANCE (km)","PLACE"})quakeGrid.Columns.Add("c"+quakeGrid.Columns.Count,h);quakeGrid.Columns[4].FillWeight=300;
  foreach(var key in new[]{"Mmax","SlipRate"})Inputs[key].TextChanged+=(s,e)=>{if(!Restoring)ApplySource();};Inputs["GeoMmax"].TextChanged+=(s,e)=>{if(Restoring)return;double gm;if(double.TryParse(Value("GeoMmax"),NumberStyles.Float,CultureInfo.InvariantCulture,out gm)&&gm>0)Inputs["Mmax"].Text=Value("GeoMmax");else if(Value("GeoMmax")==""&&!string.IsNullOrEmpty(autoMmax))Inputs["Mmax"].Text=autoMmax;};Inputs["RuptureLength"].TextChanged+=(s,e)=>{if(Restoring)return;double L;if(Value("GeoMmax")==""&&double.TryParse(Value("RuptureLength"),NumberStyles.Float,CultureInfo.InvariantCulture,out L)&&L>0&&(Value("Mmax")==""||Value("Mmax")==autoMmax)){string m=FaultTraces.Mmax(L).ToString("0.0#",CultureInfo.InvariantCulture);autoMmax=m;Inputs["Mmax"].Text=m;}};foreach(var key in new[]{"Latitude","Longitude","Radius"})Inputs[key].TextChanged+=(s,e)=>{if(!Restoring)UpdateMap();};ShowFault();}
 void UpdateMap(){double v;map.Lat=double.TryParse(Value("Latitude"),NumberStyles.Float,CultureInfo.InvariantCulture,out v)?v:double.NaN;map.Lon=double.TryParse(Value("Longitude"),NumberStyles.Float,CultureInfo.InvariantCulture,out v)?v:double.NaN;map.RadiusKm=double.TryParse(Value("Radius"),NumberStyles.Float,CultureInfo.InvariantCulture,out v)&&v>0?v:100;map.Quakes=quakes;map.Fault=estimate;map.Invalidate();}
 async Task LookUp(){double lat,lon,radius,minMag;int from;try{lat=Number("Latitude");lon=Number("Longitude");radius=Number("Radius");minMag=Number("MinMagnitude");from=(int)Number("FromYear");EarthquakeSite.ValidateCoordinates(lat,lon);if(from<1800||from>DateTime.Now.Year)throw new Exception("Earthquakes from year must be 1800 to this year.");}catch(Exception ex){sourceSummary.ForeColor=Color.Firebrick;sourceSummary.Text=ex.Message;return;}
  lookUp.Enabled=false;sourceSummary.ForeColor=PowTheme.Muted;sourceSummary.Text="Looking up the site...";var errors=new List<string>();
  try{var faultTask=Task.Run(()=>EarthquakeSite.NearestFault(lat,lon));var quakeTask=Task.Run(()=>EarthquakeSite.History(lat,lon,radius,minMag,from));
   try{fault=await faultTask;}catch(Exception ex){errors.Add("HazardHunterPH: "+Inner(ex));}
   try{quakes=await quakeTask;}catch(Exception ex){errors.Add("USGS catalog: "+Inner(ex));}}
  finally{lookUp.Enabled=true;}
  /* the rupture length measured on the fault's trace gives Mmax (Wells and Coppersmith); typed values stay */
  picked=null;try{ChooseFault(true);}catch(Exception ex){estimate=null;errors.Add("Fault traces: "+Inner(ex));}
  UpdateMap();
  ShowFault();ApplySource();if(errors.Count>0){sourceSummary.ForeColor=Color.Firebrick;sourceSummary.Text=string.Join("  ",errors)+(fault==null?"":"  "+sourceSummary.Text);}}
 static string Inner(Exception ex){while(ex.InnerException!=null)ex=ex.InnerException;return ex.Message;}
 bool Site(out double lat,out double lon){lon=double.NaN;return double.TryParse(Value("Latitude"),NumberStyles.Float,CultureInfo.InvariantCulture,out lat)&double.TryParse(Value("Longitude"),NumberStyles.Float,CultureInfo.InvariantCulture,out lon);}
 /* the site's fault: the HazardHunterPH fault in the built-in traces; if it is not there, the nearest red line of the loaded PHIVOLCS
    map; with no HazardHunterPH fault, the nearest trace. Then L, Mmax and the slip rate are filled (values the user typed stay). */
 void ChooseFault(bool lookUpDistance){double lat,lon;if(!Site(out lat,out lon))return;
  /* the PHIVOLCS fault lines (Admin edition) or a loaded map first, checked against the HazardHunterPH distance; the GEM traces give the
     slip rate and slip type of a named fault, and the fault when there are no PHIVOLCS lines */
  var gem=fault!=null?FaultTraces.ForSite(lat,lon,fault.Segment,fault.FaultName):null;var line=NearMapLine(lat,lon);
  if(line!=null){if(fault!=null){string hh=fault.Segment!=""&&fault.Segment!="ND"?fault.Segment:fault.FaultName;if(hh!="")line.Name=hh+" ("+line.Name+")";}
   if(gem!=null){line.SlipRate=gem.SlipRate;if(line.SlipType=="")line.SlipType=gem.SlipType;if(!double.IsNaN(gem.SlipRate))line.Basis+=" Slip rate "+gem.SlipRate.ToString("0.0#",CultureInfo.InvariantCulture)+" mm/yr from the GEM trace of "+gem.Name+".";}
   estimate=line;}
  else estimate=fault!=null?gem:FaultTraces.ForSite(lat,lon);
  FillFromEstimate(lookUpDistance);}
 /* the nearest PHIVOLCS map line (built into the Admin edition, or traced from a loaded KMZ), when it is plausibly the site's fault:
    within 5 km of the HazardHunterPH distance, or within 30 km with no HazardHunterPH answer */
 FaultEstimate NearMapLine(double lat,double lon){if(kmzTraces.Count==0)return null;var e=FaultTraces.ForSite(kmzTraces,lat,lon,"KMZ");if(e==null)return null;double limit=fault!=null&&!double.IsNaN(fault.DistanceKm)?fault.DistanceKm+(e.Catalog=="PHIVOLCS"?2:5):30;return e.DistanceKm<=limit?e:null;}
 void FillFromEstimate(bool setDistance){var p=fault==null?null:EarthquakeSite.Suggested(fault.FaultName);
  if(estimate!=null){string L=estimate.LengthKm.ToString("0.0",CultureInfo.InvariantCulture);if(Value("RuptureLength")==""||Value("RuptureLength")==autoLength){autoLength=L;Inputs["RuptureLength"].Text=L;}
   string m=estimate.Mmax.ToString("0.0#",CultureInfo.InvariantCulture);if(Value("GeoMmax")==""&&(Value("Mmax")==""||Value("Mmax")==autoMmax)){Inputs["Mmax"].Text=m;autoMmax=m;}else if(Value("GeoMmax")!="")autoMmax=m;
   string sr=!double.IsNaN(estimate.SlipRate)?estimate.SlipRate.ToString("0.0#",CultureInfo.InvariantCulture):p!=null?p.SlipRate.ToString("0.#",CultureInfo.InvariantCulture):"";if(Value("SlipRate")==""||Value("SlipRate")==autoSlip){Inputs["SlipRate"].Text=sr;autoSlip=sr;}}
  else if(p!=null){if(Value("Mmax")==""&&Value("GeoMmax")=="")Inputs["Mmax"].Text=p.Mmax.ToString("0.0",CultureInfo.InvariantCulture);if(Value("SlipRate")=="")Inputs["SlipRate"].Text=p.SlipRate.ToString("0.#",CultureInfo.InvariantCulture);}
  if(setDistance){if(fault!=null&&!double.IsNaN(fault.DistanceKm))Inputs["Distance"].Text=fault.DistanceKm.ToString("0.0#",CultureInfo.InvariantCulture);else if(estimate!=null)Inputs["Distance"].Text=estimate.DistanceKm.ToString("0.0#",CultureInfo.InvariantCulture);}
  ShowFault();ApplySource();}
 /* a click on a fault line takes it as the site's fault; Ctrl+click adds a part (e.g. a fault interrupted on the map) */
 void PickFault(FaultTrace t,bool add){double lat,lon;if(!Site(out lat,out lon))return;var pool=kmzTraces.Contains(t)?kmzTraces:FaultTraces.All;var group=t.Name.StartsWith("Unnamed",StringComparison.OrdinalIgnoreCase)?new List<FaultTrace>{t}:pool.Where(x=>x.Name==t.Name).ToList();
  if(add&&picked!=null){if(picked.Contains(t))picked=picked.Where(x=>!group.Contains(x)).ToList();else picked.AddRange(group);}else picked=group;
  if(picked.Count==0){picked=null;ChooseFault(false);return;}
  estimate=FaultTraces.Measure(picked,lat,lon,"picked on the map"+(picked.Any(x=>x.Catalog=="PHIVOLCS")?" (PHIVOLCS fault lines)":picked.Any(x=>x.Catalog=="KMZ")?" (PHIVOLCS map, KMZ)":"")+(fault!=null?"; the distance stays the HazardHunterPH distance":""));
  autoLength=Value("RuptureLength");autoMmax=Value("Mmax");/* a picked fault replaces the earlier automatic values */FillFromEstimate(fault==null);}
 async Task LoadKmz(string path,Button button){button.Enabled=false;kmzStatus.ForeColor=PowTheme.Muted;kmzStatus.Text="Reading the map...";
  try{var tiles=await Task.Run(()=>EarthquakeMapView.ReadKmz(path));map.Overlay=tiles;map.Invalidate();kmzStatus.Text="Tracing the red fault lines...";
   var traced=await Task.Run(()=>KmzFaultTracer.Trace(tiles));kmzTraces=new List<FaultTrace>(FaultTraces.MapLines);kmzTraces.AddRange(traced);map.Extra=kmzTraces;kmzStatus.Text=traced.Select(x=>x.Name).Distinct().Count()+" red fault lines traced from "+System.IO.Path.GetFileName(path)+" - click one to take it as the site's fault";
   if(estimate==null||estimate.Catalog=="KMZ"||estimate.Catalog=="PHIVOLCS"){picked=null;ChooseFault(false);}map.Invalidate();}
  catch(Exception ex){kmzStatus.ForeColor=Color.Firebrick;kmzStatus.Text="Fault map: "+Inner(ex);}finally{button.Enabled=true;}}
 void ApplySource(){double mmax=double.NaN,slip=double.NaN;double v;if(double.TryParse(Value("Mmax"),NumberStyles.Float,CultureInfo.InvariantCulture,out v))mmax=v;if(double.TryParse(Value("SlipRate"),NumberStyles.Float,CultureInfo.InvariantCulture,out v))slip=v;string note;string type=FaultTraces.SourceType(mmax,slip,out note);double km=double.NaN;if(double.TryParse(Value("Distance"),NumberStyles.Float,CultureInfo.InvariantCulture,out v))km=v;
  if(type!=""){((ComboBox)Inputs["Source"]).SelectedItem=type;sourceSummary.ForeColor=PowTheme.Teal;sourceSummary.Text="Seismic source type "+type+" (Table 208-3: Mmax "+mmax.ToString("0.0#",CultureInfo.InvariantCulture)+", "+(double.IsNaN(slip)?note:"slip rate "+slip.ToString("0.##",CultureInfo.InvariantCulture)+" mm/yr")+")"+(km>=15?" - at "+km.ToString("0.0",CultureInfo.InvariantCulture)+" km, Na = Nv = 1.0 for any source type (Tables 208-4, 208-5)":"")+(fault==null||double.IsNaN(fault.DistanceKm)?"":"; closest distance "+fault.DistanceKm.ToString("0.0#",CultureInfo.InvariantCulture)+" km")+" - copied to Site and structure. "+FaultTraces.Sensitivity(mmax,slip);}
  else{sourceSummary.ForeColor=PowTheme.Muted;sourceSummary.Text=fault==null?"Look up the site, or enter the fault's Mmax and slip rate to get the seismic source type.":"Enter the fault's maximum magnitude (Mmax) and slip rate from PHIVOLCS to get the seismic source type (Table 208-3).";}Refresh0();}
 void ShowFault(){if(fault==null){faultSummary.Text="No site look-up yet.";}else{var p=EarthquakeSite.Suggested(fault.FaultName);faultSummary.Text="Location: "+fault.Location+"\r\nNearest active fault: "+fault.NearestText+(fault.DateMapped>0?" (mapped "+fault.DateMapped+")":"")+"\r\nGround rupture: "+fault.GroundRupture+";  ground shaking: "+fault.GroundShaking+";  liquefaction: "+fault.Liquefaction+"\r\n"+(estimate!=null?estimate.Basis:(fault.FaultName==""?"":fault.FaultName+" is not in the built-in fault traces: load the PHIVOLCS fault map (KMZ) and click the fault, or enter its rupture length L. ")+(p==null?"Mmax and slip rate: enter them from PHIVOLCS for this fault.":p.Basis))+"\r\nSource: "+fault.Source+", retrieved "+fault.Retrieved+".";}if(fault==null&&estimate!=null)faultSummary.Text=estimate.Basis+" (HazardHunterPH not reached; distance to the trace "+estimate.DistanceKm.ToString("0.0",CultureInfo.InvariantCulture)+" km.)";UpdateMap();
  quakeGrid.Rows.Clear();foreach(var q in quakes.Take(500))quakeGrid.Rows.Add(q.TimeUtc.ToString("yyyy-MM-dd HH:mm",CultureInfo.InvariantCulture),q.Magnitude.ToString("0.0",CultureInfo.InvariantCulture)+(q.MagType==""?"":" "+q.MagType),double.IsNaN(q.DepthKm)?"":q.DepthKm.ToString("0.#",CultureInfo.InvariantCulture),q.DistanceKm.ToString("0.0",CultureInfo.InvariantCulture),q.Place);}
 /* shared with the Wind Load sheet: occupancy category I to V (Wind's III-V keeps III, IV or V; otherwise Standard, IV) and the system */
 protected override void SharedParameters(){
  Share("occupancy","Importance",v=>{int i=Array.IndexOf(Importance,v);return i<0?null:OccupancyNames[i];},(now,c)=>{int cur=Array.IndexOf(Importance,now);int i=c=="III-V"?(cur>=2?cur:3):Array.IndexOf(OccupancyNames,c);return i<0?null:Importance[i];});
  Share("system","System",v=>SystemCommon(Array.IndexOf(StaticLateralForce.Systems,v)),(now,c)=>{int i=SystemIndex(c);return i<0?null:StaticLateralForce.Systems[i];});}
 protected override bool OptionalSavedInput(string key){return new[]{"Latitude","Longitude","Radius","MinMagnitude","FromYear","RuptureLength","Mmax","SlipRate","LcLinked"}.Contains(key);}
 protected override void WriteAdditionalState(XmlElement root){if(fault!=null){var e=root.OwnerDocument.CreateElement("NearestFault");foreach(var f in typeof(FaultSite).GetFields())e.SetAttribute(f.Name,Convert.ToString(f.GetValue(fault),CultureInfo.InvariantCulture));root.AppendChild(e);}
  if(estimate!=null){var e=root.OwnerDocument.CreateElement("FaultEstimate");e.SetAttribute("name",estimate.Name);e.SetAttribute("catalog",estimate.Catalog);e.SetAttribute("slipType",estimate.SlipType);e.SetAttribute("length",estimate.LengthKm.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("mmax",estimate.Mmax.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("slipRate",estimate.SlipRate.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("distance",estimate.DistanceKm.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("basis",estimate.Basis);root.AppendChild(e);}
  var list=root.OwnerDocument.CreateElement("Earthquakes");foreach(var q in quakes){var e=root.OwnerDocument.CreateElement("Event");e.SetAttribute("time",q.TimeUtc.ToString("o",CultureInfo.InvariantCulture));e.SetAttribute("mag",q.Magnitude.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("depth",q.DepthKm.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("lat",q.Lat.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("lon",q.Lon.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("distance",q.DistanceKm.ToString("R",CultureInfo.InvariantCulture));e.SetAttribute("place",q.Place);e.SetAttribute("magType",q.MagType);e.SetAttribute("id",q.Id);list.AppendChild(e);}root.AppendChild(list);}
 protected override void ReadAdditionalState(XmlElement root){fault=null;quakes=new List<QuakeEvent>();estimate=null;picked=null;var fe=root["FaultEstimate"];if(fe!=null){Func<string,double> d=n=>{double v;return double.TryParse(fe.GetAttribute(n),NumberStyles.Float,CultureInfo.InvariantCulture,out v)?v:double.NaN;};estimate=new FaultEstimate{Name=fe.GetAttribute("name"),Catalog=fe.GetAttribute("catalog"),SlipType=fe.GetAttribute("slipType"),LengthKm=d("length"),Mmax=d("mmax"),SlipRate=d("slipRate"),DistanceKm=d("distance"),Basis=fe.GetAttribute("basis"),NearLat=double.NaN,NearLon=double.NaN};}var f=root["NearestFault"];if(f!=null){fault=new FaultSite();foreach(var field in typeof(FaultSite).GetFields()){string v=f.GetAttribute(field.Name);if(field.FieldType==typeof(string))field.SetValue(fault,v);else if(field.FieldType==typeof(double)){double d;field.SetValue(fault,double.TryParse(v,NumberStyles.Float,CultureInfo.InvariantCulture,out d)?d:double.NaN);}else if(field.FieldType==typeof(int)){int n;field.SetValue(fault,int.TryParse(v,out n)?n:0);}}}
  var list=root["Earthquakes"];if(list!=null)foreach(XmlElement e in list.SelectNodes("Event")){Func<string,double> num=n=>{double d;return double.TryParse(e.GetAttribute(n),NumberStyles.Float,CultureInfo.InvariantCulture,out d)?d:double.NaN;};quakes.Add(new QuakeEvent{TimeUtc=DateTime.Parse(e.GetAttribute("time"),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),Magnitude=num("mag"),DepthKm=num("depth"),Lat=num("lat"),Lon=num("lon"),DistanceKm=num("distance"),Place=e.GetAttribute("place"),MagType=e.GetAttribute("magType"),Id=e.GetAttribute("id")});}}
 protected override void AfterRestore(){ShowFault();ApplySource();Refresh0();}
 protected override string BuildReport(){var c=Compute();var b=new StringBuilder();
  b.AppendLine("RSA CURVE BUILDER - NSCP 2015 DESIGN RESPONSE SPECTRUM");b.AppendLine();
  b.AppendLine("## 00  SITE AND SEISMIC SOURCES");b.AppendLine("Site: "+(Value("Latitude")==""?"(coordinates not entered)":Value("Latitude")+" N, "+Value("Longitude")+" E"));
  if(fault!=null){b.AppendLine("Location: "+fault.Location);b.AppendLine("Nearest active fault: "+fault.NearestText+(fault.DateMapped>0?" (mapped "+fault.DateMapped+")":""));b.AppendLine("Ground rupture: "+fault.GroundRupture+"; ground shaking: "+fault.GroundShaking+"; liquefaction: "+fault.Liquefaction);b.AppendLine("Source: "+fault.Source+", retrieved "+fault.Retrieved+". Verify against the PHIVOLCS active fault map.");}
  else b.AppendLine("Nearest active fault: not looked up; distance and source type entered by the user.");
  {double mm,sr;bool hasM=double.TryParse(Value("Mmax"),NumberStyles.Float,CultureInfo.InvariantCulture,out mm);if(!hasM)mm=double.NaN;bool hasS=double.TryParse(Value("SlipRate"),NumberStyles.Float,CultureInfo.InvariantCulture,out sr);if(!hasS)sr=double.NaN;bool ok=hasM&&hasS;if(estimate!=null)b.AppendLine(estimate.Basis);{double L;if(double.TryParse(Value("RuptureLength"),NumberStyles.Float,CultureInfo.InvariantCulture,out L)&&L>0)b.AppendLine("Mmax from the rupture length (Wells and Coppersmith 1994, magnitude on surface rupture length, all slip types): Mmax = 5.08 + 1.16 log10(L) = 5.08 + 1.16 log10("+F(L,"0.0")+") = "+F(FaultTraces.Mmax(L),"0.00")+" (standard deviation 0.28; data: shallow crustal earthquakes, SRL 1.3 to 432 km). L is taken as the length of the fault trace (segment) that would rupture in one earthquake; parallel strands are not added."+(Math.Abs(FaultTraces.Mmax(L)-mm)>0.005&&!double.IsNaN(mm)?" Mmax used = "+F(mm,"0.0#")+" (entered).":""));}
   if(!double.IsNaN(mm)){double srv=ok?sr:double.NaN;b.AppendLine(FaultTraces.Sensitivity(mm,srv));}
   if(!ok&&!double.IsNaN(mm)){string nt;string ty=FaultTraces.SourceType(mm,double.NaN,out nt);b.AppendLine("Seismic source type (Table 208-3): Mmax = "+F(mm,"0.0#")+", "+nt+" -> Type "+ty+".");}
   if(ok){b.AppendLine("Seismic source type (Table 208-3): Mmax = "+F(mm,"0.0#")+", slip rate = "+F(sr,"0.##")+" mm/yr -> Type "+EarthquakeSite.SourceType(mm,sr)+" (A: Mmax >= 7.0 and SR >= 5; C: Mmax < 6.5 and SR <= 2; B: others).");var p=fault==null?null:EarthquakeSite.Suggested(fault.FaultName);if(p!=null)b.AppendLine(p.Basis);}}
  if(quakes.Count>0){b.AppendLine("Historical earthquakes: "+quakes.Count+" events of M"+Value("MinMagnitude")+"+ within "+Value("Radius")+" km since "+Value("FromYear")+" (USGS ANSS Comprehensive Catalog). Largest:");b.AppendLine("Date (UTC)         M     Depth (km)  Distance (km)  Place");foreach(var q in quakes.Take(15))b.AppendLine(q.TimeUtc.ToString("yyyy-MM-dd HH:mm",CultureInfo.InvariantCulture).PadRight(19)+F(q.Magnitude,"0.0").PadRight(6)+(double.IsNaN(q.DepthKm)?"":F(q.DepthKm,"0.#")).PadRight(12)+F(q.DistanceKm,"0.0").PadRight(15)+q.Place);}
  b.AppendLine();
  b.AppendLine("## 01  INPUTS");b.AppendLine("Seismic zone: Zone "+c.Zone+" (Z = "+(c.Zone==4?"0.40":"0.20")+")");b.AppendLine("Soil profile type: "+Value("Soil"));b.AppendLine("Seismic source type: "+c.Source+"; closest distance = "+F(c.Km,"0.##")+" km");b.AppendLine("Occupancy: "+Value("Importance"));b.AppendLine("R = "+F(c.R,"0.##")+"; additional scale factor = "+F(c.Extra,"0.####")+"; damping = "+F(c.Damping,"0.###"));b.AppendLine();
  b.AppendLine("## 02  SEISMIC COEFFICIENTS");
  if(c.Zone==4){b.AppendLine("Na (Table 208-4, source "+c.Source+", "+F(c.Km,"0.##")+" km, linear interpolation) = "+F(c.Na,"0.###"));b.AppendLine("Nv (Table 208-5, source "+c.Source+", "+F(c.Km,"0.##")+" km, linear interpolation) = "+F(c.Nv,"0.###"));}else b.AppendLine("Zone 2: near-source factors do not apply.");
  b.AppendLine("Ca (Table 208-7) = "+F(c.Ca,"0.####"));b.AppendLine("Cv (Table 208-8) = "+F(c.Cv,"0.####"));b.AppendLine();
  b.AppendLine("## 03  SPECTRUM SHAPE (Figure 208-3)");b.AppendLine("Ts = Cv / (2.5 Ca) = "+F(c.Cv,"0.####")+" / (2.5 x "+F(c.Ca,"0.####")+") = "+F(c.Ts,"0.####")+" s");b.AppendLine("T0 = 0.2 Ts = "+F(c.T0,"0.####")+" s");
  b.AppendLine("0 <= T < T0:  Sa = Ca (1 + 1.5 T / T0)");b.AppendLine("T0 <= T <= Ts: Sa = 2.5 Ca = "+F(2.5*c.Ca,"0.####")+" g");b.AppendLine("T > Ts:        Sa = Cv / T");b.AppendLine();
  b.AppendLine("## 04  STAAD SCALE");b.AppendLine("ACC SCALE = g x I / R x factor = "+F(c.G,"0.#####")+" x "+F(c.I,"0.##")+" / "+F(c.R,"0.##")+" x "+F(c.Extra,"0.####")+" = "+F(c.Scale,"0.######"));b.AppendLine();
  b.AppendLine("## 05  SPECTRUM ORDINATES");b.AppendLine("T (s)      Sa (g)");foreach(var p in c.Points)b.AppendLine(F(p[0],"0.0000").PadRight(11)+F(p[1],"0.00000"));b.AppendLine();
  b.AppendLine("## 06  STAAD INPUT");b.AppendLine("Dynamic (response spectrum):");b.AppendLine(Staad(c));b.AppendLine();b.AppendLine("ELF (static lateral force):");b.AppendLine(Elf(c));b.AppendLine();
  b.AppendLine("## 07  NOTES");b.AppendLine("Section 208.5.4.5: scale the dynamic base shear to not less than the static base shear requirement (90% regular / 100% irregular structures); enter the resulting ratio as the additional scale factor.");b.AppendLine("Soil profile SF and structures needing a site-specific spectrum are outside this sheet. Verify the seismic source type and distance from the PHIVOLCS fault map.");b.AppendLine("This sheet prepares analysis input only; it is not an engineer's approval.");
  return b.ToString();}
}
